#include <stdio.h>
#include <string.h>

const char *MAIN_HELP =
"bedtools is a powerful toolset for genome arithmetic.\n\n"
"Version:   b2e3657\n"
"About:     developed in the quinlanlab.org and by many contributors worldwide.\n"
"Docs:      http://bedtools.readthedocs.io/\n"
"Code:      https://github.com/arq5x/bedtools2\n"
"Mail:      https://groups.google.com/forum/#!forum/bedtools-discuss\n\n"
"Usage:     bedtools <subcommand> [options]\n\n"
"The bedtools sub-commands include:\n\n"
"[ Genome arithmetic ]\n"
"    intersect     Find overlapping intervals in various ways.\n"
"    window        Find overlapping intervals within a window around an interval.\n"
"    closest       Find the closest, potentially non-overlapping interval.\n"
"    coverage      Compute the coverage over defined intervals.\n"
"    map           Apply a function to a column for each overlapping interval.\n"
"    genomecov     Compute the coverage over an entire genome.\n"
"    merge         Combine overlapping/nearby intervals into a single interval.\n"
"    cluster       Cluster (but don't merge) overlapping/nearby intervals.\n"
"    complement    Extract intervals _not_ represented by an interval file.\n"
"    shift         Adjust the position of intervals.\n"
"    subtract      Remove intervals based on overlaps b/w two files.\n"
"    slop          Adjust the size of intervals.\n"
"    flank         Create new intervals from the flanks of existing intervals.\n"
"    sort          Order the intervals in a file.\n"
"    random        Generate random intervals in a genome.\n"
"    shuffle       Randomly redistribute intervals in a genome.\n"
"    sample        Sample random records from file using reservoir sampling.\n"
"    spacing       Report the gap lengths between intervals in a file.\n"
"    annotate      Annotate coverage of features from multiple files.\n\n"
"[ Multi-way file comparisons ]\n"
"    multiinter    Identifies common intervals among multiple interval files.\n"
"    unionbedg     Combines coverage intervals from multiple BEDGRAPH files.\n\n"
"[ Paired-end manipulation ]\n"
"    pairtobed     Find pairs that overlap intervals in various ways.\n"
"    pairtopair    Find pairs that overlap other pairs in various ways.\n\n"
"[ Format conversion ]\n"
"    bamtobed      Convert BAM alignments to BED (& other) formats.\n"
"    bedtobam      Convert intervals to BAM records.\n"
"    bamtofastq    Convert BAM records to FASTQ records.\n"
"    bedpetobam    Convert BEDPE intervals to BAM records.\n"
"    bed12tobed6   Breaks BED12 intervals into discrete BED6 intervals.\n\n"
"[ Fasta manipulation ]\n"
"    getfasta      Use intervals to extract sequences from a FASTA file.\n"
"    maskfasta     Use intervals to mask sequences from a FASTA file.\n"
"    nuc           Profile the nucleotide content of intervals in a FASTA file.\n\n"
"[ BAM focused tools ]\n"
"    multicov      Counts coverage from multiple BAMs at specific intervals.\n"
"    tag           Tag BAM alignments based on overlaps with interval files.\n\n"
"[ Statistical relationships ]\n"
"    jaccard       Calculate the Jaccard statistic b/w two sets of intervals.\n"
"    reldist       Calculate the distribution of relative distances b/w two files.\n"
"    fisher        Calculate Fisher statistic b/w two feature files.\n\n"
"[ Miscellaneous tools ]\n"
"    overlap       Computes the amount of overlap from two intervals.\n"
"    igv           Create an IGV snapshot batch script.\n"
"    links         Create a HTML page of links to UCSC locations.\n"
"    makewindows   Make interval "windows" across a genome.\n"
"    groupby       Group by common cols. & summarize oth. cols. (~ SQL "groupBy")\n"
"    expand        Replicate lines based on lists of values in columns.\n"
"    split         Split a file into multiple files with equal records or base pairs.\n"
"    summary       Statistical summary of intervals in a file.\n\n"
"[ General Parameters ]\n"
"     --cram-ref    Reference used by a CRAM input\n\n"
"[ General help ]\n"
"    --help        Print this help menu.\n"
"    --version     What version of bedtools are you using?.\n"
"    --contact     Feature requests, bugs, mailing lists, etc.\n\n";

const char *INTERSECT_HELP =
"\nTool:    bedtools intersect (aka intersectBed)\n"
"Version: b2e3657\n"
"Summary: Report overlaps between two feature files.\n\n"
"Usage:   bedtools intersect [OPTIONS] -a <bed/gff/vcf/bam> -b <bed/gff/vcf/bam>\n\n"
"\tNote: -b may be followed with multiple databases and/or \n\twildcard (*) character(s). \nOptions: \n\t-wa\tWrite the original entry in A for each overlap.\n\n\t-wb\tWrite the original entry in B for each overlap.\n\t\t- Useful for knowing _what_ A overlaps. Restricted by -f and -r.\n\n\t-loj\tPerform a "left outer join". That is, for each feature in A\n\t\treport each overlap with B.  If no overlaps are found, \n\t\treport a NULL feature for B.\n\n\t-wo\tWrite the original A and B entries plus the number of base\n\t\tpairs of overlap between the two features.\n\t\t- Overlaps restricted by -f and -r.\n\t\t  Only A features with overlap are reported.\n\n\t-wao\tWrite the original A and B entries plus the number of base\n\t\tpairs of overlap between the two features.\n\t\t- Overlapping features restricted by -f and -r.\n\t\t  However, A features w/o overlap are also reported\n\t\t  with a NULL B feature and overlap = 0.\n\n\t-u\tWrite the original A entry _once_ if _any_ overlaps found in B.\n\t\t- In other words, just report the fact >=1 hit was found.\n\t\t- Overlaps restricted by -f and -r.\n\n\t-c\tFor each entry in A, report the number of overlaps with B.\n\t\t- Reports 0 for A entries that have no overlap with B.\n\t\t- Overlaps restricted by -f, -F, -r, and -s.\n\n\t-C\tFor each entry in A, separately report the number of\n\t\t- overlaps with each B file on a distinct line.\n\t\t- Reports 0 for A entries that have no overlap with B.\n\t\t- Overlaps restricted by -f, -F, -r, and -s.\n\n\t-v\tOnly report those entries in A that have _no overlaps_ with B.\n\t\t- Similar to "grep -v" (an homage).\n\n\t-ubam\tWrite uncompressed BAM output. Default writes compressed BAM.\n\n\t-s\tRequire same strandedness.  That is, only report hits in B\n\t\tthat overlap A on the _same_ strand.\n\t\t- By default, overlaps are reported without respect to strand.\n\n\t-S\tRequire different strandedness.  That is, only report hits in B\n\t\tthat overlap A on the _opposite_ strand.\n\t\t- By default, overlaps are reported without respect to strand.\n\n\t-f\tMinimum overlap required as a fraction of A.\n\t\t- Default is 1E-9 (i.e., 1bp).\n\t\t- FLOAT (e.g. 0.50)\n\n\t-F\tMinimum overlap required as a fraction of B.\n\t\t- Default is 1E-9 (i.e., 1bp).\n\t\t- FLOAT (e.g. 0.50)\n\n\t-r\tRequire that the fraction overlap be reciprocal for A AND B.\n\t\t- In other words, if -f is 0.90 and -r is used, this requires\n\t\t  that B overlap 90% of A and A _also_ overlaps 90% of B.\n\n\t-e\tRequire that the minimum fraction be satisfied for A OR B.\n\t\t- In other words, if -e is used with -f 0.90 and -F 0.10 this requires\n\t\t  that either 90% of A is covered OR 10% of  B is covered.\n\t\t  Without -e, both fractions would have to be satisfied.\n\n\t-split\tTreat "split" BAM or BED12 entries as distinct BED intervals.\n\n\t-g\tProvide a genome file to enforce consistent chromosome sort order\n\t\tacross input files. Only applies when used with -sorted option.\n\n\t-nonamecheck\tFor sorted data, don't throw an error if the file has different naming conventions\n\t\t\tfor the same chromosome. ex. "chr1" vs "chr01".\n\n\t-sorted\tUse the "chromsweep" algorithm for sorted (-k1,1 -k2,2n) input.\n\n\t-names\tWhen using multiple databases, provide an alias for each that\n\t\twill appear instead of a fileId when also printing the DB record.\n\n\t-filenames\tWhen using multiple databases, show each complete filename\n\t\t\tinstead of a fileId when also printing the DB record.\n\n\t-sortout\tWhen using multiple databases, sort the output DB hits\n\t\t\tfor each record.\n\n\t-bed\tIf using BAM input, write output as BED.\n\n\t-header\tPrint the header from the A file prior to results.\n\n\t-nobuf\tDisable buffered output. Using this option will cause each line\n\t\tof output to be printed as it is generated, rather than saved\n\t\tin a buffer. This will make printing large output files \n\t\tnoticeably slower, but can be useful in conjunction with\n\t\tother software tools and scripts that need to process one\n\t\tline of bedtools output at a time.\n\n\t-iobuf\tSpecify amount of memory to use for input buffer.\n\t\tTakes an integer argument. Optional suffixes K/M/G supported.\n\t\tNote: currently has no effect with compressed files.\n\nNotes: \n\t(1) When a BAM file is used for the A file, the alignment is retained if overlaps exist,\n\tand excluded if an overlap cannot be found.  If multiple overlaps exist, they are not\n\treported, as we are only testing for one or more overlaps.\n\n\n";

const char *CONTACT =
"\n- For further help, or to report a bug, please \n"
"  email the bedtools mailing list: \n"
"     bedtools-discuss@googlegroups.com\n\n"
"- The development repository can be found at: \n"
"     https://github.com/arq5x/bedtools\n\n"
"- Stable releases of bedtools can be found at: \n"
"     https://github.com/arq5x/bedtools2/releases\n\n";

int main(int argc, char **argv) {
    if (argc == 1) {
        printf("%s", MAIN_HELP);
        return 0;
    }
    // Single option flags
    if (strcmp(argv[1], "--help") == 0) {
        printf("%s", MAIN_HELP);
        return 0;
    }
    if (strcmp(argv[1], "--version") == 0) {
        printf("bedtools b2e3657\n");
        return 0;
    }
    if (strcmp(argv[1], "--contact") == 0) {
        printf("%s", CONTACT);
        return 0;
    }
    if (strcmp(argv[1], "help") == 0) {
        printf("error: unrecognized command: help\n");
        return 0;
    }
    if (strcmp(argv[1], "intersect") == 0) {
        // if any argument is -h or --help, print intersect help
        for (int i = 2; i < argc; ++i) {
            if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
                printf("%s", INTERSECT_HELP);
                return 0;
            }
        }
        // default to printing intersect help if no args
        if (argc == 2) {
            printf("%s", INTERSECT_HELP);
            return 0;
        }
        // otherwise for other options, just print intersect help as fallback
        printf("%s", INTERSECT_HELP);
        return 0;
    }

    // Unknown command: print main help
    printf("%s", MAIN_HELP);
    return 0;
}
EOF

cat > compile.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
gcc -O2 -std=c11 main.c -o executable
chmod +x executable
EOF

chmod +x compile.sh

# add .gitignore
cat > .gitignore <<'EOF'
executable
EOF

# git commit
git add main.c compile.sh .gitignore
git commit -m "Reimplement bedtools help CLI stub" || true

# verify build
./compile.sh

# quick checks
./executable --version
./executable --help | sed -n '1,20p'
./executable intersect -h | sed -n '1,12p'

EOF"}

